import java.util.*;

public class Harness {
    static void check(int[] coinsArr, int total, Integer[] expected) {
        List<Integer> coins = new ArrayList<>();
        for (int c : coinsArr) coins.add(c);
        List<Integer> got = new ChangeCalculator(coins).computeMostEfficientChange(total);
        String g = got.toString();
        String e = Arrays.toString(expected);
        System.out.println((g.equals(e) ? "OK   " : "FAIL ") + "coins=" + Arrays.toString(coinsArr)
                + " total=" + total + " got=" + g + " expected=" + e);
    }
    static void checkError(int[] coinsArr, int total, String msg) {
        List<Integer> coins = new ArrayList<>();
        for (int c : coinsArr) coins.add(c);
        try {
            new ChangeCalculator(coins).computeMostEfficientChange(total);
            System.out.println("FAIL no exception for " + total);
        } catch (IllegalArgumentException ex) {
            System.out.println((msg.equals(ex.getMessage()) ? "OK   " : "FAIL ") + "total=" + total
                    + " msg=" + ex.getMessage());
        }
    }
    public static void main(String[] args) {
        check(new int[]{1,5,10,25}, 1, new Integer[]{1});
        check(new int[]{1,5,10,25,100}, 25, new Integer[]{25});
        check(new int[]{1,5,10,25,100}, 15, new Integer[]{5,10});
        check(new int[]{1,4,15,20,50}, 23, new Integer[]{4,4,15});
        check(new int[]{1,5,10,21,25}, 63, new Integer[]{21,21,21});
        check(new int[]{1,2,5,10,20,50,100}, 999, new Integer[]{2,2,5,20,20,50,100,100,100,100,100,100,100,100,100});
        check(new int[]{2,5,10,20,50}, 21, new Integer[]{2,2,2,5,10});
        check(new int[]{4,5}, 27, new Integer[]{4,4,4,5,5,5});
        check(new int[]{1,10,11}, 20, new Integer[]{10,10});
        check(new int[]{1,5,10,21,25}, 0, new Integer[]{});
        checkError(new int[]{5,10}, 3, "The total 3 cannot be represented in the given currency.");
        checkError(new int[]{5,10}, 94, "The total 94 cannot be represented in the given currency.");
